import 'dart:convert';
import 'dart:typed_data';

import 'package:fl_clash/services/age_crypto.dart';
import 'package:test/test.dart';

// Generated by the Core's Go age library with the public age specification's
// identity (32 bytes of 0x42), including an unrecognized recipient stanza.
const _goCiphertext = '''
-----BEGIN AGE ENCRYPTED FILE-----
YWdlLWVuY3J5cHRpb24ub3JnL3YxCi0+IGV4YW1wbGUuY29tL2lnbm9yZWQKWm1s
NGRIVnlaUQotPiBYMjU1MTkgTGhBZHNVSjNZbGRFOTZaQW9VUXpuc2RIRlVWMmQ2
bGtGRVhsSkpzVEdBTQpOSDlSTHFzV29RZ0VBWlYyd0lvcTNGMW9OdlZBdEtUTHVD
S0xuVWttdDJFCi0tLSBFZ3hGUmd5dmFzQklwaVQ0ZytFZTJldXY0ZDJhQTZDTVBF
TU1ZZjVjNVlBCncNQeH1R6nKPFZiYOyPOGPLQhGzP1dLGAw2tUMsM6nMYvM+JeH6
jk+Y1fo0VPfFWeu83X/ErCU=
-----END AGE ENCRYPTED FILE-----
''';

const _zeroShareCiphertext = '''
-----BEGIN AGE ENCRYPTED FILE-----
YWdlLWVuY3J5cHRpb24ub3JnL3YxCi0+IFgyNTUxOSBBQUFBQUFBQUFBQUFBQUFB
QUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBCm96QzhNMGEvTjJPcUh4VVJjazly
TklQNXlFYkZBRXZoVXFIQld3QkhuTG8KLS0tIFFCUkZWcWtjSUs4SUwzMVNBNm1l
NkJlNjc1RzNobVNlWFY2VE53c3RzeE0K/F23b0UMNDZ1Z0Z0+9RoX9L3g9+7kb5Y
oY3InE3FvIFRj+Rh5suR/wZmMhnZ5tS9Qc7MQMrjPQ==
-----END AGE ENCRYPTED FILE-----
''';

Uint8List _alterHeader(String Function(String header) alter) {
  final binary = base64Decode(
    const LineSplitter().convert(_goCiphertext).skip(1).take(6).join(),
  );
  final text = latin1.decode(binary);
  final end = text.indexOf('\n', text.indexOf('\n--- ') + 1) + 1;
  final modified = [
    ...latin1.encode(alter(text.substring(0, end))),
    ...binary.sublist(end),
  ];
  final encoded = base64Encode(modified);
  return utf8.encode(
    [
      '-----BEGIN AGE ENCRYPTED FILE-----',
      ...RegExp('.{1,64}').allMatches(encoded).map((m) => m.group(0)!),
      '-----END AGE ENCRYPTED FILE-----',
      '',
    ].join('\n'),
  );
}

void main() {
  late AgeIdentity identity;
  setUpAll(() async {
    identity = await AgeCrypto.identityFromSeed(List.filled(32, 0x42));
  });

  test(
    'decrypts a Go age file with an unrecognized recipient stanza',
    () async {
      final plaintext = await AgeCrypto.decrypt(
        utf8.encode(_goCiphertext),
        identity,
      );
      expect(utf8.decode(plaintext), 'mode: rule\nproxies: []\n');
    },
  );

  test('rejects a modified header MAC', () async {
    final changed = _alterHeader((header) {
      final mac = header.indexOf('\n--- ') + 5;
      return header.replaceRange(mac, mac + 1, header[mac] == 'A' ? 'B' : 'A');
    });
    await expectLater(
      AgeCrypto.decrypt(changed, identity),
      throwsFormatException,
    );
  });

  test('authenticates unrecognized recipient stanzas too', () async {
    final changed = _alterHeader(
      (header) =>
          header.replaceFirst('example.com/ignored', 'example.net/ignored'),
    );
    await expectLater(
      AgeCrypto.decrypt(changed, identity),
      throwsFormatException,
    );
  });

  test('rejects a missing header MAC', () async {
    final changed = _alterHeader(
      (header) => header.replaceFirst(RegExp(r'--- [^\n]+'), '--- '),
    );
    await expectLater(
      AgeCrypto.decrypt(changed, identity),
      throwsFormatException,
    );
  });

  test('rejects a padded header MAC', () async {
    final changed = _alterHeader(
      (header) => header.replaceFirstMapped(
        RegExp(r'--- ([^\n]+)'),
        (match) => '--- ${match[1]}=',
      ),
    );
    await expectLater(
      AgeCrypto.decrypt(changed, identity),
      throwsFormatException,
    );
  });

  test(
    'rejects a low-order ephemeral key with a valid MAC and payload',
    () async {
      await expectLater(
        AgeCrypto.decrypt(utf8.encode(_zeroShareCiphertext), identity),
        throwsFormatException,
      );
    },
  );

  test('rejects a low-order encryption recipient', () async {
    await expectLater(
      AgeCrypto.encrypt(utf8.encode('mode: rule\n'), Uint8List(32)),
      throwsFormatException,
    );
  });

  for (final size in [0, 65536, 65537]) {
    test('authenticated age round-trip at $size bytes', () async {
      final plaintext = Uint8List.fromList(List.generate(size, (i) => i % 251));
      final ciphertext = await AgeCrypto.encrypt(
        plaintext,
        identity.publicKeyBytes,
      );
      expect(await AgeCrypto.decrypt(ciphertext, identity), plaintext);
    });
  }
}
